pub const fn new() -> Self {
    Vec { buf: RawVec::new(), len: 0 }
}

pub fn try_reserve_exact(&mut self, additional: usize) -> Result<(), TryReserveError> {
    self.buf.try_reserve_exact(self.len, additional)
}

pub fn resize(&mut self, new_len: usize, value: T) {
    let len = self.len();

    if new_len > len {
        self.extend_with(new_len - len, value)
    } else {
        self.truncate(new_len);
    }
}

fn extend_with(&mut self, n: usize, value: T) {
    self.reserve(n);

    unsafe {
        let mut ptr = self.as_mut_ptr().add(self.len());
        // Use SetLenOnDrop to work around bug where compiler
        // might not realize the store through `ptr` through self.set_len()
        // don't alias.
        let mut local_len = SetLenOnDrop::new(&mut self.len);

        // Write all elements except the last one
        for _ in 1..n {
            ptr::write(ptr, value.clone());
            ptr = ptr.add(1);
            // Increment the length in every step in case clone() panics
            local_len.increment_len(1);
        }

        if n > 0 {
            // We can write the last element directly without cloning needlessly
            ptr::write(ptr, value);
            local_len.increment_len(1);
        }

        // len set by scope guard
    }
}

pub(crate) fn try_reserve_exact(
    &mut self,
    len: usize,
    additional: usize,
) -> Result<(), TryReserveError> {
    // SAFETY: All calls on self.inner pass T::LAYOUT as the elem_layout
    unsafe { self.inner.try_reserve_exact(len, additional, T::LAYOUT) }
}

unsafe fn try_reserve_exact(
    &mut self,
    len: usize,
    additional: usize,
    elem_layout: Layout,
) -> Result<(), TryReserveError> {
    if self.needs_to_grow(len, additional, elem_layout) {
        // SAFETY: Precondition passed to caller
        unsafe {
            self.grow_exact(len, additional, elem_layout)?;
        }
    }
    unsafe {
        // Inform the optimizer that the reservation has succeeded or wasn't needed
        hint::assert_unchecked(!self.needs_to_grow(len, additional, elem_layout));
    }
    Ok(())
}

unsafe fn grow_exact(
    &mut self,
    len: usize,
    additional: usize,
    elem_layout: Layout,
) -> Result<(), TryReserveError> {
    if elem_layout.size() == 0 {
        // Since we return a capacity of `usize::MAX` when the type size is
        // 0, getting to here necessarily means the `RawVec` is overfull.
        return Err(CapacityOverflow.into());
    }

    let cap = len.checked_add(additional).ok_or(CapacityOverflow)?;

    // SAFETY: preconditions passed to caller
    let ptr = unsafe { self.finish_grow(cap, elem_layout)? };

    // SAFETY: `finish_grow` would have failed if `cap > isize::MAX`
    unsafe { self.set_ptr_and_cap(ptr, cap) };
    Ok(())
}

unsafe fn finish_grow(
    &self,
    cap: usize,
    elem_layout: Layout,
) -> Result<NonNull<[u8]>, TryReserveError> {
    let new_layout = layout_array(cap, elem_layout)?;

    let memory = if let Some((ptr, old_layout)) = unsafe { self.current_memory(elem_layout) } {
        // FIXME(const-hack): switch to `debug_assert_eq`
        debug_assert!(old_layout.align() == new_layout.align());
        unsafe {
            // The allocator checks for alignment equality
            hint::assert_unchecked(old_layout.align() == new_layout.align());
            self.alloc.grow(ptr, old_layout, new_layout)
        }
    } else {
        self.alloc.allocate(new_layout)
    };

    // FIXME(const-hack): switch back to `map_err`
    match memory {
        Ok(memory) => Ok(memory),
        Err(_) => Err(AllocError { layout: new_layout, non_exhaustive: () }.into()),
    }
}

pub unsafe fn alloc(layout: Layout) -> *mut u8 {
    unsafe {
        // Make sure we don't accidentally allow omitting the allocator shim in
        // stable code until it is actually stabilized.
        __rust_no_alloc_shim_is_unstable_v2();

        __rust_alloc(layout.size(), layout.alignment())
    }
}

fn allocate(&self, layout: Layout) -> Result<NonNull<[u8]>, AllocError> {
    self.alloc_impl(layout, false)
}

unsafe fn grow(
    &self,
    ptr: NonNull<u8>,
    old_layout: Layout,
    new_layout: Layout,
) -> Result<NonNull<[u8]>, AllocError> {
    // SAFETY: all conditions must be upheld by the caller
    unsafe { self.grow_impl(ptr, old_layout, new_layout, false) }
}

pub const fn handle_alloc_error(layout: Layout) -> ! {
    const fn ct_error(_: Layout) -> ! {
        panic!("allocation failed");
    }

    #[inline]
    fn rt_error(layout: Layout) -> ! {
        unsafe {
            __rust_alloc_error_handler(layout.size(), layout.align());
        }
    }

    #[cfg(not(panic = "immediate-abort"))]
    {
        core::intrinsics::const_eval_select((layout,), ct_error, rt_error)
    }

    #[cfg(panic = "immediate-abort")]
    ct_error(layout)
}

unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
    let alignment = layout.alignment();
    // SAFETY: the caller must ensure that the `new_size` does not overflow
    // when rounded up to the next multiple of `alignment`.
    let new_layout = unsafe { Layout::from_size_alignment_unchecked(new_size, alignment) };
    // SAFETY: the caller must ensure that `new_layout` is greater than zero.
    let new_ptr = unsafe { self.alloc(new_layout) };
    if !new_ptr.is_null() {
        // SAFETY: the previously allocated block cannot overlap the newly allocated block.
        // The safety contract for `dealloc` must be upheld by the caller.
        unsafe {
            ptr::copy_nonoverlapping(ptr, new_ptr, cmp::min(layout.size(), new_size));
            self.dealloc(ptr, layout);
        }
    }
    new_ptr
}
